CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS stores (slug TEXT PRIMARY KEY, owner_id TEXT UNIQUE NOT NULL, name TEXT, mode TEXT, wa TEXT, tier TEXT NOT NULL DEFAULT 'free', status TEXT NOT NULL DEFAULT 'active', data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS orders (slug TEXT NOT NULL, id TEXT NOT NULL, ts INTEGER NOT NULL, type TEXT, total REAL, status TEXT, cname TEXT, cphone TEXT, lines TEXT, PRIMARY KEY (slug, id));
CREATE INDEX IF NOT EXISTS orders_slug_ts ON orders (slug, ts);
CREATE TABLE IF NOT EXISTS views (slug TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS images (id TEXT PRIMARY KEY, slug TEXT NOT NULL, mime TEXT NOT NULL, data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS images_slug ON images (slug);
